"""Stage 3 merge for report 28."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C240","product-rule","Never interrupt the completion moment — no ad, upsell or rating prompt on the check-off tap","Report 28: a forced full-screen interstitial fired on every habit check-off is the single largest fact in an 821-review corpus — 164 complaints (19.98%, mean 2.73 vs 4.35 for every other review; 52.4% of all 1★), 33 naming the per-tap mechanic as a punishment ('it feels like a punishment for doing what you were meant to do'; 'replacing the feel-good with this uncanny worry'), 30 calling the app unusable, 19 five-star reviewers still complaining, and the users most helped by the reward loop (ADHD) the most damaged by breaking it. Users are not asking for zero ads; they propose batching ('let me tick them all off and then show me an ad') or a cap per session. Report 24: checking off one habit takes 3–5 screens of celebration; report 25: upsell sheets on every action; a 2026 rating prompt fired on check-off produced a 1★ purely about the prompt.")
add("C241","product-rule","Sell entitlements as non-consumables — a consumable currency cannot be restored and has no 'paid member' state to honour","Report 28: one consumable currency ('carrots') sells cosmetics, functional caps, ad removal and cloud sync; 10 of 24 identifiable payers (41.7%) report a purchase that did not deliver or could not be restored — 'I paid 10$ to remove ads but I still get ads'; 'cannot restore purchase on a new device'; 'I paid the 14.99… it's still saying I need to purchase'; and a $10 buyer is charged again when a new paid feature ships ('i'm already a paid member; why do i have to make another purchase?'). Reviewers cannot tell what they are buying ('I now realize just buying anything gives u cloud access') and ask for it unbundled ('just pay like two dollars to just get unlimited tasks'). An architecture problem presenting as a trust problem.")

ext("C082", " Report 28 (the strongest counter-evidence in the set): an ad-supported free tier whose interstitial fires on every check-off is 19.98% of reviews at mean 2.73 vs 4.35 for the rest, 52.4% of all 1★, and rose from 3.5% (2021H2) to 39.6% (2024H2) before easing to 16.7%; three reports of non-dismissible ads and one of 'decline the rewarded ad, get a forced ad anyway' are store-guideline risks; an app rated 4+ with 40 reviews from or about children (ages 8–10 self-declared) serves untargeted network ads including AI homework-cheating and Temu wigs; 6 reviewers praise the ads as light and rewarded ads for carrots are accepted — the placement, not the existence, is the damage; the CN storefront (12 reviews, zero ad complaints) may be a natural ad-free control.")
ext("C127", " Report 28: 'I paid 10$ to remove ads but I still get ads'; a 5★ 'purchased the full version and I am still getting ads' — and even after buying no-ads there is still a prompt to double carrots by watching an ad after every level.")
ext("C006", " Report 28 (the other side): a gamified pet-and-rooms tracker whose ad load — not its game — is 52% of the worst outcome the store measures; 'do not simplify away the gamification' is the report's first 'what not to change'.")
ext("C033", " Report 28: 10 of 24 identifiable payers (41.7%) report a purchase not delivered or not restorable — a $9.99 pack that never appeared with 'no Support button in the app. Nor on developer's website'; restore failing on a new device with the same account; a purchased cosmetic that reverted; consumables cannot be restored the way non-consumables can.")
ext("C139", " Report 28: 'I paid the 14.99 to unlock the full app 2 days ago and it's still saying I need to purchase it… Total scam'; carrots not delivered after 2–3 hours with restart and restore both failing.")
ext("C036", " Report 28: 'There is no Support button in the app. Nor on developer's website'; 'no matter how many emails you send, they don't reply'; yet the four who reached the developer got excellent service — a 1★ converted to 5★ after a verification reset 'within an hour… on a Sunday, on a 3 day holiday weekend'; support quality is not the problem, discoverability is — an in-app 'Contact support' and 'Restore purchases' entry point is the cheapest rating intervention available.")
ext("C142", " Report 28: an in-app 'Restore purchases' and 'Contact support' entry point is missing — four purchase failures and two 'where do I get help' reviews, while the developer answers e-mail within hours.")
ext("C059", " Report 28: a 1★ upgraded to 5★ after one support e-mail ('The devs pay attention. 5 stars now'); bugs collapsed from 11.3% (2023) to 0.7% (2025) after a genuine stabilisation.")
ext("C063", " Report 28: five reviewers wanted to pay and were stopped by the absence of a trial — 'I wouldn't have purchased until I was sure I liked the app, and it was impossible to like the app when it was a slew of ads'; 'Unlike Study Bunny, there is no $2.00 30-day trial… that's a full STOP sign'; the dominant purchase trigger is ad removal after sustained free use, which the 'unusable' churners never reach; the sibling app's reported $2 / 30-day trial is the proposed experiment.")
ext("C007", " Report 28: a habit-count cap of ~8 (17, 2.07%) plus a priority-slot cap of 1 red / 2 orange (15, 1.83%) and paid moods (10); 'Had trouble finding a habit tracker that didn't need a subscription to add more than three habits' and 'free tier usage incredibly wide compared to other trackers' are stated reasons for choosing it; cap complaints fell 8.5% → 3.8% mainly because the ad load crowded them out.")
ext("C133", " Report 28: capping semantics — how important a user is allowed to say something is (1 red / 2 orange priority slots) — reads as the app overruling the user: 'it feels disingenuous to put exercise as low priority just so that i can put washing my face as medium'; 'if I put hygiene as yellow it's just wrong'; if a cap must stay, rename the tiers as labels or let users choose colours; a to-do list that earns nothing while habits do is the same class of gate.")
ext("C075", " Report 28: 38 onboarding complaints (4.63%, mean 3.24) with one unchanged content for four and a half years — the tutorial teaches the fiction (bunny, mess, carrots) but not how to add, edit or delete a habit ('The tutorial is pointless as they don't show you how to create a task'; 'a steep learning curve with all the unlabeled icons'); 11 more report the add/edit controls genuinely broken and the app cannot tell which it is receiving; the fix is a labelled, skippable tutorial that demonstrates habit CRUD.")
ext("C040", " Report 28: no widget at all — 14 requests (1.71%), mean 4.64, zero negative ratings, continuous April 2022 → September 2026, 'i want to be able to click on the widget and shortcut to check a habit as done'; the clearest uncontested gap in the corpus.")
ext("C023", " Report 28: an interactive check-off widget requested continuously for four and a half years by satisfied users (mean 4.64, zero negatives).")
ext("C043", " Report 28: a weekly-target-only model — monthly, every-other-week, multiple-times-per-day and specific-weekday scheduling requested by 15 (1.83%), one explicitly blocking a purchase: 'I can't see myself purchasing without being able to make these distinctions'.")
ext("C027", " Report 28: 21 localisation requests/defects (2.56%) — Spanish 5, Turkish 3, Chinese 3, Japanese 2, Russian 2, French, Thai, Arabic, Portuguese; two are defects on an existing localisation (Japanese glyphs rendered for Chinese, habit names truncated; untranslated English with Chinese selected) and a 2022 localisation update rendered every 'r' as a black square; rest-of-world markets rate higher (4.181 vs 3.956) and are 5× more blocked by language (5.56% vs 1.09%) — 'the cheapest lever in the highest-satisfaction segment'; two name language as why they leave.")
ext("C228", " Report 28: CJK font fallback rendered Japanese glyphs for Chinese text and silently truncated habit names; a localisation update once turned every 'r' into a black square — audit font fallback and string handling whenever a language ships.")
ext("C034", " Report 28: 12 data/progress-loss reports (1.46%, mean 2.42) entangled with the game's intentional decay — 'on challenge mode… run out of health it resets ALL of your progress… level 278… resets you to level 1'; 'My Account is gone, I was at a high Level'; an intentional decay mechanic and an unintentional data-loss bug are indistinguishable to the user.")
ext("C157", " Report 28: rabbit health/energy decay with guilt notifications ('YOUR BUNNY'S LOSING HEALTH COME AND DO HABITS TO FIX IT!') and a challenge-mode full reset penalise exactly the cautious beginner ('I have few habits because I'm starting a healthier lifestyle slowly'); a defender values the stakes — make decay a setting, separate it visibly from the data model.")
ext("C216", " Report 28: decay that resets 'ALL of your progress' after a bad week is read as data loss; a gentler or optional decay with a visible backup state would separate punishment from bugs.")
ext("C237", " Report 28: users complete all rooms and the motivation engine stops — 16 (1.95%), including a paying customer leaving ('this one doesn't motivate me anymore'), 'after level 200 you get items less frequently, and the hype is gone', 'incentives stop after level three hundred'; one specifies the remedy — reset the house and make it dirty again, counting resets like a prestige.")
ext("C117", " Report 28: the rabbit is the emotional object — 40 (4.87%, mean 4.15) describe attachment ('I named him Paul'; 'so I dont abandon my rabbit child'), the room-cleaning loop is 'an externalised progress bar with an emotional stake' (60, mean 4.25), 244 (29.72%) describe concrete behaviour change ('made me lose 80 pounds'; 'I take my iron pill just to check it off'); the cute art survives even in 12 of 84 one-star reviews; a bug that made the rabbit drift off-screen when tapped ('I WAS TAPPING ON THE BUNNY AND IT FLEW AWAY') drew 12 reports; users want to pet and feed it (9).")
ext("C024", " Report 28: gamification (carrots, levels, rooms, a pet) is the differentiator in an 821-review corpus — but 10 (mean 2.40) say 'it's a game, not a tracker', an expectation mismatch the listing could pre-empt.")
ext("C178", " Report 28 (counter-evidence): the gamified pet loop is what works here — 'especially having adhd, this gamification works so well for my brain'; one reviewer chose it because it is less feature-heavy than Finch; the plain/gamified split is a positioning choice, not a rule.")
ext("C042", " Report 28: ADHD/autism users (15, mean 4.33) say the reward loop 'works so well for my brain' — and produce the harshest ad verdicts ('whenever I click to complete a habit, it shows me an advert'; 'Bad for ADHD — Has Potential'): interruption cost is not evenly distributed; kids and students are 40 (4.87%), several aged 8–10.")
ext("C103", " Report 28: an app rated 4+ with 40 reviews (4.87%) from or about children — 'I'm ten'; 'im nine'; 'I am a 8 years old' — serves untargeted network ads (AI homework-cheating apps, Temu wigs) and a 'watch an ad to double carrots' prompt; a brand and compliance exposure independent of the rating damage.")
ext("C162", " Report 28: untargeted ad content inside a 4+ app used by self-declared 8–10-year-olds and by a teacher with students — 'ads for AI homework apps that will write papers for you… encouraging bad habits through these ads'.")
ext("C060", " Report 28: cross-promotion from the sibling app Study Bunny drove launch (31.8% of 2021 reviews, a beta-forgiving cohort with zero 1★) and still drives a tenth of reviews, but fell to 3.8% by 2026 — the app now acquires on its own store presence, so the rating and the ad policy are commercially decisive; users ask for single sign-on and a shared bunny across the family.")
ext("C094", " Report 28: a rating prompt on open and on check-off shipped in 2026 (5 of 7 complaints are 2026) and already produced a 1★ 'until the rate me notification spam gets fixed'; 134 contentless 5★ records (median 38 chars) suggest the 2026 rating recovery is partly solicited; 'prompting into an ad-frustrated session is actively harvesting negative ratings'.")
ext("C150", " Report 28: 'Every time I checked something off it would ask me to rate it' (5★, asking it to stop) — a prompt fired on the completion tap.")
ext("C056", " Report 28: zero of 821 reviews request AI features; the only AI mention is a complaint about AI homework-cheating ads served inside the app — 'no evidence of AI demand in this audience'.")
ext("C064", " Report 28: 16 price objections (1.95%, mean 2.88) at ~$10–15 consumable tiers — 'too expensive for an unproven, ad-saturated experience, sold as an opaque bundle, with no way to try it'; 'not the level of quality that this kind of money gets you with apps like procreate'; students and minors cannot pay ('strict parents and only my mom knows my Apple ID'); the winning position is 'more affordable alternative' to Finch — do not raise the price.")
ext("C005", " Report 28: 13 (1.58%, mean 4.15) arrive from other trackers — 'a more affordable and functional alternative to another well known self care pet' (Finch), 'Not overloaded with features and tabs (like Finch)', 'didn't need a subscription to add more than three habits'; the losing comparison is a full teardown against Finch where multi-device sync wins and no trial plus ad load lose.")
ext("C134", " Report 28: 'It's a game, not a tracker' (10, mean 2.40 — 'not at all what I was expecting'; 'the only thing I'm tracking is the amount of adds') is a listing and first-run expectation-setting problem costing 2★ reviews with no defect present.")
ext("C218", " Report 28: a listing that says 'habit tracker' for a product that is a pet game produces 'it's not what it says it is' 2★ reviews.")
ext("C031", " Report 28: launch failure / crash 15 (1.83%, mean 2.40) concentrated in 2022 (orange-screen failure), then a 2026 uptick ('freezing every time I open the app, I think it needs an update to keep up with ios') consistent with OS drift on a build last updated Nov 2025.")
ext("C175", " Report 28: a listing version ten months older than the newest reviews coincides with 2026 freezing, crashing and broken-login reports — 'verify the app on current iOS and ship an update'; the 2022 rabbit-off-screen, can't-clean-the-room and orange-screen bugs were fixed and stayed fixed.")
ext("C071", " Report 28: 'incentives stop after level three hundred… makes me assume the developers have taken their hands off the wheel'; the listing's last version is ten months stale.")
ext("C013", " Report 28: cloud sync is bundled with any purchase ('I now realize just buying anything gives u cloud access'; 'il faut payer pour jumeler les comptes'); multi-device sync is named as the advantage over Finch.")
ext("C188", " Report 28: offline use is reported as paid and then removed; 6 complain about an internet requirement (mean 3.83).")
ext("C035", " Report 28: an account with e-mail verification exists (29 mentions, mean 3.66, mixed); a verification reset by support turned a 1★ into a 5★.")
ext("C050", " Report 28: a to-do checklist exists separately from habits and users want it to earn carrots (9, mean 4.44 — 'the more irksome and time consuming tasks that you procrastinate on').")
ext("C049", " Report 28: a mood tracker with limited free moods (paid moods 10 complaints, mean 3.90; mood entry mandatory on open 2); journal/mood used by 38 (4.63%, mean 4.29).")
ext("C172", " Report 28: journal/notes per day and mood tracking used by 38 (4.63%, mean 4.29).")
ext("C141", " Report 28: iPad / larger-screen support requested by 6 (mean 4.67); screen-fit / aspect-ratio defects 5.")
ext("C066", " Report 28: a timer with auto-mark-complete exists; three want it to run in the background / on the lock screen.")
ext("C016", " Report 28: 'the only way to remove a habit from view is to delete it, but that results in losing all its data'; one wants to mark a routine as 'established' and retire it.")
ext("C062", " Report 28: the high-spend group (us, cn, jp, gb, de, fr, kr, ca, au, tw = 67.1%) rates lower (3.956 vs 4.181) with ad complaints 5.5pp higher and paywall friction 2.5× higher; GB complains about ads more than the US yet rates higher ('I love this, please fix the ads'); the US carries 71% of payers and the most precise criticism.")
ext("C231", " Report 28: China (n=12) has zero ad complaints while its three critical reviews are all localisation — if ad inventory does not serve there, CN is a natural control for the ad-free product.")
ext("C002", " Report 28: the offer here is an ad load — its half-year complaint rate (3.5% → 39.6% → 16.7%) and the corpus mean (4.729 → 3.810 → 4.048) move together; 2021 had zero 1★ and the launch honeymoon never returned.")
ext("C065", " Report 28: identifiable payers rate 3.75 vs 4.03 and 41.7% of them report a failed purchase; a 5★ payer still getting ads writes 'Maybe it just needs to sync up'.")
ext("C119", " Report 28: UI bloat / update regression 6 (0.73%, mean 2.50); 'Seems like every update just brings more paywall and more forced advertisements'.")
ext("C039", " Report 28: notification annoyance 5 (0.61%, mean 2.80) — decay-guilt pushes ('YOUR BUNNY'S LOSING HEALTH').")
ext("C061", " Report 28: 'I've spent money on this app SOLELY to support the developer because I can't thank him enough'; 'the actual habit tracking is FREE' praised by 13.")
ext("C093", " Report 28: forced interstitials on every action ('Ad while you write a habit. Ad while you review habits. Ad while you breathe.') and a rating prompt on open and check-off.")
ext("C004", " Report 28: a $6.98 skin, $9.99–$14.99 consumable packs; 'Study bunny costs like $15-20 so the price could go up for this one too… kind of uncool'.")
ext("C020", " Report 28: no export mentioned; cloud sync paid.")

